 # ------------- skeleton dto for the transactions ---------------------
import uuid
from typing import Literal, Optional,List
from datetime import date, datetime
import pandas as pd
import re

import fitz # PyMuPDF


class TransactionDTO:
    """
    Data Transfer Object for Finance Transactions.
    """
    id: uuid.UUID
    date: date
    amount: float
    bank_description: str
    details: Optional[str]
    txn_type: Literal["CREDIT", "DEBIT"]
    transaction_id: Optional[str]  # Bank transaction ID or similar
    utr_number: Optional[str] # UPI transaction ID
    audit_status: Optional[Literal["MATCHED", "UNMATCHED", "FLAGGED"]] # Status after matching with UPI/other records
    duplicate_transaction_id: Optional[uuid.UUID] # Link to a potential duplicate transaction
    reference_number: Optional[str] # New field for Ref No./Cheque No.
    bank_name: str # New field for bank name
    payment_method: Optional[str] # New field for payment method (UPI, NEFT, IMPS, etc.)


    def __init__(self,
                 id: uuid.UUID,
                 date: date,
                 amount: float,
                 bank_description: str,
                 details: Optional[str],
                 txn_type: Literal["CREDIT", "DEBIT"],
                 bank_name: str, # Add bank_name to init
                 payment_method: Optional[str] = None, # Add payment_method to init
                 transaction_id: Optional[str] = None,
                 utr_number: Optional[str] = None,
                 audit_status: Optional[Literal["MATCHED", "UNMATCHED", "FLAGGED"]] = None,
                 duplicate_transaction_id: Optional[uuid.UUID] = None,
                 reference_number: Optional[str] = None): # Add reference_number to init
        self.id = id
        self.date = date
        self.amount = amount
        self.bank_description = bank_description
        self.details = details
        self.txn_type = txn_type
        self.bank_name = bank_name # Assign bank_name
        self.payment_method = payment_method # Assign payment_method
        self.transaction_id = transaction_id
        self.utr_number = utr_number
        self.audit_status = audit_status
        self.duplicate_transaction_id = duplicate_transaction_id
        self.reference_number = reference_number # Assign reference_number

    def __repr__(self):
        return (f"TransactionDTO(id={self.id!r}, date={self.date!r}, amount={self.amount!r}, "
                f"bank_description={self.bank_description!r}, details={self.details!r}, "
                f"txn_type={self.txn_type!r}, bank_name={self.bank_name!r}, payment_method={self.payment_method!r}, transaction_id={self.transaction_id!r}, "
                f"utr_number={self.utr_number!r}, audit_status={self.audit_status!r}, "
                f"duplicate_transaction_id={self.duplicate_transaction_id!r}, "
                f"reference_number={self.reference_number!r})") # Add bank_name and payment_method to repr

    def __eq__(self, other):
        if not isinstance(other, TransactionDTO):
            return NotImplemented
        return self.id == other.id

    def __hash__(self):
        return hash(self.id)

def load_excel_file(file_path="sbi_txn.xlsx",skiprows=20,usecols=None):
  try:
      # Read the Excel file starting from row 21 (index 20)
      df_sbi = pd.read_excel(file_path, skiprows=skiprows,usecols=usecols)
      print("Successfully read the Excel file.")

      # print(df_sbi.head())
      return df_sbi
  except FileNotFoundError:
      print(f"Error: File not found at {file_path}")
  except Exception as e:
      print(f"An error occurred while reading the Excel file: {e}")

def parse_sbi_description(description: str) -> dict:
  parsed_data = {'utr_number': None, 'details': None, 'payment_method': None} # Add payment_method

  if isinstance(description, str):
      # Handle UPI transfers
      if 'UPI/' in description:
          cleaned_description = description.replace('TO TRANSFER-', '').replace('BY TRANSFER-', '').strip()
          match = re.search(r'UPI/(DR|CR)/(\d+)/.*?/.*?/(.*)', cleaned_description)
          if match:
              parsed_data['utr_number'] = match.group(2)
              parsed_data['details'] = match.group(3).strip()
          parsed_data['payment_method'] = 'UPI' # Set payment method to UPI
      # Handle Credit Interest
      elif 'CREDIT INTEREST' in description:
          parsed_data['details'] = 'Credit Interest'
          parsed_data['utr_number'] = None
          parsed_data['payment_method'] = 'Interest' # Set payment method to Interest
      # Handle Bulk Posting (often NACH or other bulk transfers)
      elif 'BULK POSTING' in description:
          # Example: BULK POSTING-ACHCr HDFC05717000027455 TATAMOTO...
          match = re.search(r'BULK POSTING-(.*)', description)
          if match:
              parsed_data['details'] = match.group(1).strip()
          parsed_data['utr_number'] = None # Bulk posting typically doesn't have a UTR
          # You might want to refine this based on patterns within BULK POSTING description
          if 'ACH' in description:
              parsed_data['payment_method'] = 'NACH' # Assuming ACH in description means NACH
          else:
              parsed_data['payment_method'] = 'Bulk Transfer' # Generic for other bulk postings
      # Handle other formats (NEFT, IMPS, etc.) if they appear in SBI statements
      elif 'NEFT' in description:
           parsed_data['payment_method'] = 'NEFT'
           neft_match = re.search(r'NEFT-([^-]+)-(.*)', description)
           if neft_match:
              parsed_data['utr_number'] = neft_match.group(1)
              parsed_data['details'] = neft_match.group(2).strip()
      elif 'IMPS' in description:
           parsed_data['payment_method'] = 'IMPS'
           imps_match = re.search(r'IMPS/(\d+)/(\d+)/(.*?)/', description)
           if imps_match:
               parsed_data['utr_number'] = imps_match.group(1)
               parsed_data['details'] = f"IMPS A/C: {imps_match.group(2)}, Details: {imps_match.group(3).strip()}"
      # Handle ATM withdrawals
      elif 'ATM WDL' in description:
          parsed_data['payment_method'] = 'ATM Withdrawal'
          parsed_data['details'] = description
      # Handle POS transactions
      elif 'POS' in description:
           parsed_data['payment_method'] = 'POS'
           parsed_data['details'] = description
      # Handle other transaction types as needed
      else:
          parsed_data['details'] = description
          parsed_data['utr_number'] = None
          parsed_data['payment_method'] = 'Other' # Default to 'Other' if no specific pattern matches

  return parsed_data

def parse_icici_description(description: str) -> dict:
    """
    Parses the ICICI transaction description string to extract relevant details and payment method.
    """
    parsed_data = {'utr_number': None, 'details': None, 'payment_method': None} # Add payment_method

    if isinstance(description, str):
        # Attempt to find UPI details based on the specified format
        # UPI/SenderName/comment/receiverBank/UTRNumber/transactionId
        match_upi = re.search(r'UPI/(.*?)/(.*?)/(.*?)/(\d+)/(.*)', description)
        if match_upi:
            parsed_data['utr_number'] = match_upi.group(4) # UTR number is in the 4th group
            parsed_data['details'] = match_upi.group(2).strip() # Comment (details) is in the 2nd group
            parsed_data['payment_method'] = 'UPI' # Set payment method to UPI
        elif 'NEFT-' in description:
            parsed_data['payment_method'] = 'NEFT' # Set payment method to NEFT
            neft_match = re.search(r'NEFT-([^-]+)-(.*)', description)
            if neft_match:
                parsed_data['utr_number'] = neft_match.group(1) # NEFT UTR/Reference
                parsed_data['details'] = neft_match.group(2).strip()
        elif 'IMPS/' in description:
            parsed_data['payment_method'] = 'IMPS' # Set payment method to IMPS
            imps_match = re.search(r'IMPS/(\d+)/(\d+)/(.*?)/', description)
            if imps_match:
                parsed_data['utr_number'] = imps_match.group(1) # IMPS reference
                # details could be the third group or combination
                parsed_data['details'] = f"IMPS A/C: {imps_match.group(2)}, Details: {imps_match.group(3).strip()}"
        # Handle NACH transactions (look for patterns like 'NACH')
        elif 'NACH' in description or 'ACH' in description:
            parsed_data['payment_method'] = 'NACH'
            parsed_data['details'] = description # Keep full description for NACH details initially
        # Handle ATM withdrawals
        elif 'ATM WDL' in description:
            parsed_data['payment_method'] = 'ATM Withdrawal'
            parsed_data['details'] = description
        # Handle POS transactions
        elif 'POS' in description:
            parsed_data['payment_method'] = 'POS'
            parsed_data['details'] = description
        # Add more patterns as needed for other transaction types
        else:
             parsed_data['details'] = description
             parsed_data['utr_number'] = None
             parsed_data['payment_method'] = 'Other' # Default to 'Other'

    return parsed_data


def convert_sbi_to_txn_dto(data) -> TransactionDTO:
  # Extract data from the dictionary
    txn_date = data.get('Txn Date')
    value_date = data.get('Value Date') # Although not directly used in DTO, good to extract
    description = data.get('Description', '')
    ref_no = data.get('Ref No./Cheque No.') # Optional
    debit_amount = data.get('Debit')
    credit_amount = data.get('Credit')
    balance = data.get('Balance') # Not directly used in DTO, but available

    # Debugging: Print the type and value of txn_date
    # print(f"Debugging: Txn Date: {txn_date}, Type: {type(txn_date)}")


    # Determine transaction type and amount
    txn_type = None
    amount = 0.0
    if pd.notna(debit_amount):
        txn_type = "DEBIT"
        amount = float(debit_amount)
    elif pd.notna(credit_amount):
        txn_type = "CREDIT"
        amount = float(credit_amount)

    # Convert date to date object
    # Assuming 'Txn Date' is a pandas Timestamp or datetime object
    transaction_date = None
    if isinstance(txn_date, (pd.Timestamp, datetime)): # Check for both Timestamp and datetime
        transaction_date = txn_date.date()
    # Handle potential None or other types if necessary, though iterrows typically yields Timestamps


    utr_number = None
    details = None
    payment_method = None # Initialize payment_method

    # Use the new parsing function for description
    parsed_details = parse_sbi_description(description)
    utr_number = parsed_details.get('utr_number')
    details = parsed_details.get('details')
    payment_method = parsed_details.get('payment_method') # Get payment_method


    # Create TransactionDTO object
    if txn_type is not None: # Only create DTO if transaction type is determined
        dto = TransactionDTO(
            id=uuid.uuid4(), # Generate a unique ID
            date=transaction_date,
            amount=amount,
            bank_description=description,
            details=details,
            txn_type=txn_type,
            bank_name="SBI", # Set bank name
            payment_method=payment_method, # Assign payment_method
            transaction_id=None, # No direct mapping for transaction_id in source data
            utr_number=utr_number,
            audit_status=None,
            duplicate_transaction_id=None,
            reference_number=str(ref_no) if pd.notna(ref_no) else None # Add reference_number
        )
        return dto
    # print(f"invalid transactions {data}")
    return None

def convert_icici_to_txn_dto(data) -> TransactionDTO:
    """
    Converts a dictionary from an ICICI bank transaction row into a TransactionDTO.
    """
    # Extract data from the dictionary based on ICICI column names
    txn_date = data.get('Transaction Date')
    value_date = data.get('Value Date') # Although not directly used in DTO, good to extract
    description = data.get('Transaction Remarks', '')
    ref_no_cheque_no = data.get('Cheque Number')
    debit_amount = data.get('Withdrawal Amount (INR )')
    credit_amount = data.get('Deposit Amount (INR )')
    balance = data.get('Balance (INR )') # Not directly used in DTO, but available

    # Determine transaction type and amount
    txn_type = None
    amount = 0.0
    if pd.notna(debit_amount) and debit_amount > 0:
        txn_type = "DEBIT"
        amount = float(debit_amount)
    elif pd.notna(credit_amount) and credit_amount > 0:
        txn_type = "CREDIT"
        amount = float(credit_amount)

    # Convert date to date object
    transaction_date = None
    # Assuming 'Transaction Date' is in 'DD/MM/YYYY' format based on observed data
    if isinstance(txn_date, str):
        try:
            # Adjust format string if necessary based on actual data format
            transaction_date = datetime.strptime(txn_date, '%d/%m/%Y').date()
        except ValueError:
            # Handle cases where the date format might be different or invalid
            print(f"Could not parse date: {txn_date}")
            return None
    elif isinstance(txn_date, (pd.Timestamp, datetime)): # Handle if already datetime object
         transaction_date = txn_date.date()
    else:
        # If txn_date is None or unexpected type, skip this row
        return None


    utr_number = None
    details = None
    payment_method = None # Initialize payment_method

    # Use the new parsing function for description
    parsed_details = parse_icici_description(description)
    utr_number = parsed_details.get('utr_number')
    details = parsed_details.get('details')
    payment_method = parsed_details.get('payment_method') # Get payment_method


    # Create TransactionDTO object
    if txn_type is not None and transaction_date is not None: # Only create DTO if essential data is determined
        dto = TransactionDTO(
            id=uuid.uuid4(), # Generate a unique ID
            date=transaction_date,
            amount=amount,
            bank_description=description,
            details=details,
            txn_type=txn_type,
            bank_name="ICICI", # Set bank name
            payment_method=payment_method, # Assign payment_method
            transaction_id=None, # No direct mapping for transaction_id in source data
            utr_number=utr_number,
            audit_status=None,
            duplicate_transaction_id=None,
            reference_number=str(ref_no_cheque_no) if pd.notna(ref_no_cheque_no) else None
        )
        return dto

    # print(f"Skipping invalid transaction row: {data}")
    return None

def convert_phonepe_to_txn_dto(data) -> TransactionDTO:
    """
    Converts a dictionary from a PhonePe transaction row into a TransactionDTO.
    """
    # Extract data from the dictionary based on PhonePe DataFrame column names
    txn_date = data.get('date')
    description = data.get('bank_description', '')
    amount = data.get('amount')
    txn_type = data.get('txn_type')
    transaction_id = data.get('transaction_id')
    utr_number = data.get('utr_number')
    details = data.get('details')
    reference_number = data.get('reference_number')
    payment_method = data.get('payment_method') # Get payment_method from DataFrame


    # Convert date to date object if it's not already
    transaction_date = None
    if isinstance(txn_date, str):
        try:
            # Assuming 'date' is already in 'YYYY-MM-DD' format from previous cleaning
            transaction_date = datetime.strptime(txn_date, '%Y-%m-%d').date()
        except ValueError:
             # If date format is different, try other common formats or handle appropriately
             print(f"Could not parse date from string: {txn_date}")
             return None
    elif isinstance(txn_date, (pd.Timestamp, datetime, date)): # Handle if already date/datetime object
         transaction_date = txn_date if isinstance(txn_date, date) else txn_date.date()
    else:
        # If txn_date is None or unexpected type, skip this row
        print(f"Skipping row due to invalid date type: {type(txn_date)}")
        return None


    # Ensure amount is a float
    try:
        amount = float(amount) if pd.notna(amount) else 0.0
    except ValueError:
        print(f"Could not convert amount to float: {amount}")
        return None


    # Create TransactionDTO object
    if txn_type is not None and transaction_date is not None and amount is not None: # Only create DTO if essential data is determined
        dto = TransactionDTO(
            id=uuid.uuid4(), # Generate a unique ID for the DTO
            date=transaction_date,
            amount=amount,
            bank_description=description,
            details=details,
            txn_type=txn_type,
            bank_name="PhonePe", # Set bank name to PhonePe
            payment_method=payment_method, # Assign payment_method from DataFrame
            transaction_id=transaction_id,
            utr_number=utr_number,
            audit_status=None, # PhonePe data doesn't have this, default None
            duplicate_transaction_id=None, # PhonePe data doesn't have this, default None
            reference_number=reference_number
        )
        return dto

    # print(f"Skipping invalid transaction row: {data}")
    return None


# generic funciton to parse over the dto converter.
def get_transactions_list(data,f) -> List[TransactionDTO]:
  transaction_dto_list = []

  # Iterate over the rows of the DataFrame and convert each row to a TransactionDTO
  for index, row in data.iterrows():
      transaction_dict = row.to_dict()
      # print(transaction_dict)
      dto = f(transaction_dict)
      if dto:  # Only append if the conversion was successful and returned a DTO
          transaction_dto_list.append(dto)

  print(f"Created {len(transaction_dto_list)} TransactionDTO objects.")
  return transaction_dto_list

def save_data_to_csv(transaction_dto_list:List[TransactionDTO],file_name='sbi_transactions.csv'):

  # Convert list of TransactionDTO objects to a list of dictionaries
  data_for_df = [dto.__dict__ for dto in transaction_dto_list]

  # Convert the list of dictionaries to a pandas DataFrame
  df_output = pd.DataFrame(data_for_df)

  # Define the output CSV file path
  output_csv_filepath = os.path.join(bank_txn_path, file_name)

  # Save the DataFrame to a CSV file
  df_output.to_csv(output_csv_filepath, index=False)

  print(f"Successfully saved transaction data to CSV file: {output_csv_filepath}")



def extract_text_from_pdf(pdf_path):
    """
    Extracts text from a PDF file using PyMuPDF.
    """
    doc = fitz.open(phonepe_pdf_path)
    text = ""
    for page_num in range(doc.page_count):
        page = doc.load_page(page_num)
        text += page.get_text()
    return text

def parse_phonepe_transactions(text):
    """
    Parses the text of a PhonePe statement to extract transaction data.

    Args:
        text: The string content of the PhonePe statement.

    Returns:
        A list of dictionaries, where each dictionary represents a transaction.
    """
    transactions = []
    # Regex to find each transaction block, which starts with a date and time
    transaction_blocks = re.split(r'\n(?=\w{3}\s\d{2},\s\d{4}\n\d{2}:\d{2}\s[AP]M)', text)

    for block in transaction_blocks:
        if not block.strip() or "Transaction Statement for" in block:
            continue

        try:
            # Extracting date and time
            date_match = re.search(r'(\w{3}\s\d{2},\s\d{4})', block)
            time_match = re.search(r'(\d{2}:\d{2}\s[AP]M)', block)
            date = date_match.group(1) if date_match else None
            time = time_match.group(1) if time_match else None

            # Extracting transaction type and amount
            type_amount_match = re.search(r'(DEBIT|CREDIT)\s₹([\d,]+\.?\d*)', block)
            txn_type = type_amount_match.group(1) if type_amount_match else None
            amount_str = type_amount_match.group(2) if type_amount_match else '0'
            amount = float(amount_str.replace(',', ''))

            # Extracting Transaction ID
            txn_id_match = re.search(r'Transaction ID\s(.+?)\n', block)
            transaction_id = txn_id_match.group(1).strip() if txn_id_match else None

            # Extracting UTR No.
            utr_match = re.search(r'UTR No\.\s(.+?)\n', block)
            utr_number = utr_match.group(1).strip() if utr_match else None

            # Extracting Paid by/Credited to
            paid_by_match = re.search(r'Paid by\n(.+?)\n', block)
            credited_to_match = re.search(r'Credited to\n(.+?)\n', block)
            account = paid_by_match.group(1).strip() if paid_by_match else (credited_to_match.group(1).strip() if credited_to_match else None)

            # Extracting Transaction Details
            details_match = re.search(r'\d{2}:\d{2}\s[AP]M\n(.*?)\nTransaction ID', block, re.DOTALL)
            details = details_match.group(1).strip().replace('\n', ' ') if details_match else None

            if date and time and txn_type and amount is not None:
                transactions.append({
                    "Date": date,
                    "Time": time,
                    "Transaction Details": details,
                    "Type": txn_type,
                    "Amount": amount,
                    "Transaction ID": transaction_id,
                    "UTR No.": utr_number,
                    "Account": account
                })
        except Exception as e:
            print(f"Error parsing block: {block}\n{e}")
    return pd.DataFrame(transactions)


import uuid

def clean_and_format_phonepe_df(phonepe_df):
  if 'Date' in phonepe_df.columns:
      phonepe_df['Date'] = pd.to_datetime(phonepe_df['Date'], format='%b %d, %Y').dt.date
      # Rename 'Date' to 'date' to match DTO expectation
      phonepe_df = phonepe_df.rename(columns={'Date': 'date'})

  # Ensure 'amount' is float (it should be from initial parsing)
  if 'Amount' in phonepe_df.columns:
      phonepe_df['Amount'] = phonepe_df['Amount'].astype(float)
      phonepe_df = phonepe_df.rename(columns={'Amount': 'amount'})


  # Drop 'Time' if it exists
  if 'Time' in phonepe_df.columns:
      phonepe_df = phonepe_df.drop(columns=['Time'])

  # Rename other columns to match DTO schema if they exist with old names
  if 'Transaction Details' in phonepe_df.columns:
      phonepe_df = phonepe_df.rename(columns={'Transaction Details': 'bank_description'})
  if 'Type' in phonepe_df.columns:
      phonepe_df = phonepe_df.rename(columns={'Type': 'txn_type'})
  if 'Transaction ID' in phonepe_df.columns:
      phonepe_df = phonepe_df.rename(columns={'Transaction ID': 'transaction_id'})
  if 'UTR No.' in phonepe_df.columns:
      phonepe_df = phonepe_df.rename(columns={'UTR No.': 'utr_number'})
  if 'Account' in phonepe_df.columns:
      phonepe_df = phonepe_df.rename(columns={'Account': 'details'})


  # Add missing DTO columns if they don't exist (should not exist in raw data)
  if 'bank_name' not in phonepe_df.columns:
      phonepe_df['bank_name'] = 'PhonePe'
  if 'id' not in phonepe_df.columns:
      # Generate UUIDs only if 'id' column doesn't exist
      phonepe_df['id'] = [uuid.uuid4() for _ in range(len(phonepe_df))]
  if 'reference_number' not in phonepe_df.columns:
      phonepe_df['reference_number'] = None
  if 'audit_status' not in phonepe_df.columns:
      phonepe_df['audit_status'] = None
  if 'duplicate_transaction_id' not in phonepe_df.columns:
      phonepe_df['duplicate_transaction_id'] = None
  # Add payment_method - default to UPI for PhonePe as most transactions are UPI
  if 'payment_method' not in phonepe_df.columns:
      phonepe_df['payment_method'] = 'UPI'


  # Reorder columns to match TransactionDTO schema before conversion
  phonepe_df = phonepe_df[['id', 'date', 'amount', 'bank_description', 'details', 'txn_type',
                          'bank_name', 'payment_method', 'transaction_id', 'utr_number', 'audit_status',
                          'duplicate_transaction_id', 'reference_number']]
  return phonepe_df

