def audit_bank_transactions(bank_txn,phonepe):
  combined_bank_transactions_df = bank_txn
  # Convert 'date' columns to datetime objects if not already
  combined_bank_transactions_df['date'] = pd.to_datetime(combined_bank_transactions_df['date'])
  phonepe['date'] = pd.to_datetime(phonepe['date'])

  amount_tolerance = 0.01 # Define a small tolerance for amount comparison
  date_tolerance = pd.Timedelta(days=1) # Define a tolerance for date comparison

  # Iterate through combined bank transactions
  for bank_index, bank_txn in combined_bank_transactions_df.iterrows():
      # Iterate through PhonePe transactions to find a match
      for phonepe_index, phonepe_txn in phonepe.iterrows():

          # Matching criteria:
          # 1. Matching UTR number (if available in both)
          utr_match = False
          if pd.notna(phonepe_txn['utr_number']) and pd.notna(bank_txn['utr_number']):
              # Convert UTR numbers to string for comparison, handling potential non-numeric values and floats
              phonepe_utr_str = str(phonepe_txn['utr_number']).split('.')[0] if isinstance(phonepe_txn['utr_number'], float) else str(phonepe_txn['utr_number'])
              bank_utr_str = str(bank_txn['utr_number']).split('.')[0] if isinstance(bank_txn['utr_number'], float) else str(bank_txn['utr_number'])

              if phonepe_utr_str == bank_utr_str:
                  utr_match = True

          # 2. Close date proximity
          date_match = False
          if pd.notna(phonepe_txn['date']) and pd.notna(bank_txn['date']):
              date_match = abs(phonepe_txn['date'] - bank_txn['date']) <= date_tolerance


          # 3. Similar amount
          amount_match = False
          if pd.notna(phonepe_txn['amount']) and pd.notna(bank_txn['amount']):
              amount_match = abs(phonepe_txn['amount'] - bank_txn['amount']) <= amount_tolerance


          # Combine criteria for a potential match
          if utr_match or (date_match and amount_match):
              # Update the audit_status and system_comment for the bank transaction
              combined_bank_transactions_df.loc[bank_index, 'audit_status'] = 'MATCHED'
              combined_bank_transactions_df.loc[bank_index, 'system_comment'] = 'Found in PhonePe'
              # Break the inner loop once a match is found for the current bank transaction
              break
  return combined_bank_transactions_df

combined_bank_transactions_df = audit_bank_transactions(combined_bank_txn,phonepe)
