def extract_text_from_pdf(pdf_path):
    """
    Extracts text from a PDF file using PyMuPDF.
    """
    doc = fitz.open(phonepe_pdf_path)
    text = ""
    for page_num in range(doc.page_count):
        page = doc.load_page(page_num)
        text += page.get_text()
    return text

def parse_phonepe_transactions(text):
    """
    Parses the text of a PhonePe statement to extract transaction data.

    Args:
        text: The string content of the PhonePe statement.

    Returns:
        A list of dictionaries, where each dictionary represents a transaction.
    """
    transactions = []
    # Regex to find each transaction block, which starts with a date and time
    transaction_blocks = re.split(r'\n(?=\w{3}\s\d{2},\s\d{4}\n\d{2}:\d{2}\s[AP]M)', text)

    for block in transaction_blocks:
        if not block.strip() or "Transaction Statement for" in block:
            continue

        try:
            # Extracting date and time
            date_match = re.search(r'(\w{3}\s\d{2},\s\d{4})', block)
            time_match = re.search(r'(\d{2}:\d{2}\s[AP]M)', block)
            date = date_match.group(1) if date_match else None
            time = time_match.group(1) if time_match else None

            # Extracting transaction type and amount
            type_amount_match = re.search(r'(DEBIT|CREDIT)\s₹([\d,]+\.?\d*)', block)
            txn_type = type_amount_match.group(1) if type_amount_match else None
            amount_str = type_amount_match.group(2) if type_amount_match else '0'
            amount = float(amount_str.replace(',', ''))

            # Extracting Transaction ID
            txn_id_match = re.search(r'Transaction ID\s(.+?)\n', block)
            transaction_id = txn_id_match.group(1).strip() if txn_id_match else None

            # Extracting UTR No.
            utr_match = re.search(r'UTR No\.\s(.+?)\n', block)
            utr_number = utr_match.group(1).strip() if utr_match else None

            # Extracting Paid by/Credited to
            paid_by_match = re.search(r'Paid by\n(.+?)\n', block)
            credited_to_match = re.search(r'Credited to\n(.+?)\n', block)
            account = paid_by_match.group(1).strip() if paid_by_match else (credited_to_match.group(1).strip() if credited_to_match else None)

            # Extracting Transaction Details
            details_match = re.search(r'\d{2}:\d{2}\s[AP]M\n(.*?)\nTransaction ID', block, re.DOTALL)
            details = details_match.group(1).strip().replace('\n', ' ') if details_match else None

            if date and time and txn_type and amount is not None:
                transactions.append({
                    "Date": date,
                    "Time": time,
                    "Transaction Details": details,
                    "Type": txn_type,
                    "Amount": amount,
                    "Transaction ID": transaction_id,
                    "UTR No.": utr_number,
                    "Account": account
                })
        except Exception as e:
            print(f"Error parsing block: {block}\n{e}")
    return pd.DataFrame(transactions)


import uuid

def clean_and_format_phonepe_df(phonepe_df):
  if 'Date' in phonepe_df.columns:
      phonepe_df['Date'] = pd.to_datetime(phonepe_df['Date'], format='%b %d, %Y').dt.date
      # Rename 'Date' to 'date' to match DTO expectation
      phonepe_df = phonepe_df.rename(columns={'Date': 'date'})

  # Ensure 'amount' is float (it should be from initial parsing)
  if 'Amount' in phonepe_df.columns:
      phonepe_df['Amount'] = phonepe_df['Amount'].astype(float)
      phonepe_df = phonepe_df.rename(columns={'Amount': 'amount'})


  # Drop 'Time' if it exists
  if 'Time' in phonepe_df.columns:
      phonepe_df = phonepe_df.drop(columns=['Time'])

  # Rename other columns to match DTO schema if they exist with old names
  if 'Transaction Details' in phonepe_df.columns:
      phonepe_df = phonepe_df.rename(columns={'Transaction Details': 'bank_description'})
  if 'Type' in phonepe_df.columns:
      phonepe_df = phonepe_df.rename(columns={'Type': 'txn_type'})
  if 'Transaction ID' in phonepe_df.columns:
      phonepe_df = phonepe_df.rename(columns={'Transaction ID': 'transaction_id'})
  if 'UTR No.' in phonepe_df.columns:
      phonepe_df = phonepe_df.rename(columns={'UTR No.': 'utr_number'})
  if 'Account' in phonepe_df.columns:
      phonepe_df = phonepe_df.rename(columns={'Account': 'details'})


  # Add missing DTO columns if they don't exist (should not exist in raw data)
  if 'bank_name' not in phonepe_df.columns:
      phonepe_df['bank_name'] = 'PhonePe'
  if 'id' not in phonepe_df.columns:
      # Generate UUIDs only if 'id' column doesn't exist
      phonepe_df['id'] = [uuid.uuid4() for _ in range(len(phonepe_df))]
  if 'reference_number' not in phonepe_df.columns:
      phonepe_df['reference_number'] = None
  if 'audit_status' not in phonepe_df.columns:
      phonepe_df['audit_status'] = None
  if 'duplicate_transaction_id' not in phonepe_df.columns:
      phonepe_df['duplicate_transaction_id'] = None
  # Add payment_method - default to UPI for PhonePe as most transactions are UPI
  if 'payment_method' not in phonepe_df.columns:
      phonepe_df['payment_method'] = 'UPI'


  # Reorder columns to match TransactionDTO schema before conversion
  phonepe_df = phonepe_df[['id', 'date', 'amount', 'bank_description', 'details', 'txn_type',
                          'bank_name', 'payment_method', 'transaction_id', 'utr_number', 'audit_status',
                          'duplicate_transaction_id', 'reference_number']]
  return phonepe_df

