 # ------------- skeleton dto for the transactions ---------------------
import uuid
from typing import Literal, Optional,List
from datetime import date, datetime
import pandas as pd
import re

import fitz # PyMuPDF


class TransactionDTO:
    """
    Data Transfer Object for Finance Transactions.
    """
    id: uuid.UUID
    date: date
    amount: float
    bank_description: str
    details: Optional[str]
    txn_type: Literal["CREDIT", "DEBIT"]
    transaction_id: Optional[str]  # Bank transaction ID or similar
    utr_number: Optional[str] # UPI transaction ID
    audit_status: Optional[Literal["MATCHED", "UNMATCHED", "FLAGGED"]] # Status after matching with UPI/other records
    duplicate_transaction_id: Optional[uuid.UUID] # Link to a potential duplicate transaction
    reference_number: Optional[str] # New field for Ref No./Cheque No.
    bank_name: str # New field for bank name
    payment_method: Optional[str] # New field for payment method (UPI, NEFT, IMPS, etc.)


    def __init__(self,
                 id: uuid.UUID,
                 date: date,
                 amount: float,
                 bank_description: str,
                 details: Optional[str],
                 txn_type: Literal["CREDIT", "DEBIT"],
                 bank_name: str, # Add bank_name to init
                 payment_method: Optional[str] = None, # Add payment_method to init
                 transaction_id: Optional[str] = None,
                 utr_number: Optional[str] = None,
                 audit_status: Optional[Literal["MATCHED", "UNMATCHED", "FLAGGED"]] = None,
                 duplicate_transaction_id: Optional[uuid.UUID] = None,
                 reference_number: Optional[str] = None): # Add reference_number to init
        self.id = id
        self.date = date
        self.amount = amount
        self.bank_description = bank_description
        self.details = details
        self.txn_type = txn_type
        self.bank_name = bank_name # Assign bank_name
        self.payment_method = payment_method # Assign payment_method
        self.transaction_id = transaction_id
        self.utr_number = utr_number
        self.audit_status = audit_status
        self.duplicate_transaction_id = duplicate_transaction_id
        self.reference_number = reference_number # Assign reference_number

    def __repr__(self):
        return (f"TransactionDTO(id={self.id!r}, date={self.date!r}, amount={self.amount!r}, "
                f"bank_description={self.bank_description!r}, details={self.details!r}, "
                f"txn_type={self.txn_type!r}, bank_name={self.bank_name!r}, payment_method={self.payment_method!r}, transaction_id={self.transaction_id!r}, "
                f"utr_number={self.utr_number!r}, audit_status={self.audit_status!r}, "
                f"duplicate_transaction_id={self.duplicate_transaction_id!r}, "
                f"reference_number={self.reference_number!r})") # Add bank_name and payment_method to repr

    def __eq__(self, other):
        if not isinstance(other, TransactionDTO):
            return NotImplemented
        return self.id == other.id

    def __hash__(self):
        return hash(self.id)

