def parse_sbi_description(description: str) -> dict:
  parsed_data = {'utr_number': None, 'details': None, 'payment_method': None} # Add payment_method

  if isinstance(description, str):
      # Handle UPI transfers
      if 'UPI/' in description:
          cleaned_description = description.replace('TO TRANSFER-', '').replace('BY TRANSFER-', '').strip()
          match = re.search(r'UPI/(DR|CR)/(\d+)/.*?/.*?/(.*)', cleaned_description)
          if match:
              parsed_data['utr_number'] = match.group(2)
              parsed_data['details'] = match.group(3).strip()
          parsed_data['payment_method'] = 'UPI' # Set payment method to UPI
      # Handle Credit Interest
      elif 'CREDIT INTEREST' in description:
          parsed_data['details'] = 'Credit Interest'
          parsed_data['utr_number'] = None
          parsed_data['payment_method'] = 'Interest' # Set payment method to Interest
      # Handle Bulk Posting (often NACH or other bulk transfers)
      elif 'BULK POSTING' in description:
          # Example: BULK POSTING-ACHCr HDFC05717000027455 TATAMOTO...
          match = re.search(r'BULK POSTING-(.*)', description)
          if match:
              parsed_data['details'] = match.group(1).strip()
          parsed_data['utr_number'] = None # Bulk posting typically doesn't have a UTR
          # You might want to refine this based on patterns within BULK POSTING description
          if 'ACH' in description:
              parsed_data['payment_method'] = 'NACH' # Assuming ACH in description means NACH
          else:
              parsed_data['payment_method'] = 'Bulk Transfer' # Generic for other bulk postings
      # Handle other formats (NEFT, IMPS, etc.) if they appear in SBI statements
      elif 'NEFT' in description:
           parsed_data['payment_method'] = 'NEFT'
           neft_match = re.search(r'NEFT-([^-]+)-(.*)', description)
           if neft_match:
              parsed_data['utr_number'] = neft_match.group(1)
              parsed_data['details'] = neft_match.group(2).strip()
      elif 'IMPS' in description:
           parsed_data['payment_method'] = 'IMPS'
           imps_match = re.search(r'IMPS/(\d+)/(\d+)/(.*?)/', description)
           if imps_match:
               parsed_data['utr_number'] = imps_match.group(1)
               parsed_data['details'] = f"IMPS A/C: {imps_match.group(2)}, Details: {imps_match.group(3).strip()}"
      # Handle ATM withdrawals
      elif 'ATM WDL' in description:
          parsed_data['payment_method'] = 'ATM Withdrawal'
          parsed_data['details'] = description
      # Handle POS transactions
      elif 'POS' in description:
           parsed_data['payment_method'] = 'POS'
           parsed_data['details'] = description
      # Handle other transaction types as needed
      else:
          parsed_data['details'] = description
          parsed_data['utr_number'] = None
          parsed_data['payment_method'] = 'Other' # Default to 'Other'

  return parsed_data

def parse_icici_description(description: str) -> dict:
    """
    Parses the ICICI transaction description string to extract relevant details and payment method.
    """
    parsed_data = {'utr_number': None, 'details': None, 'payment_method': None} # Add payment_method

    if isinstance(description, str):
        # Attempt to find UPI details based on the specified format
        # UPI/SenderName/comment/receiverBank/UTRNumber/transactionId
        match_upi = re.search(r'UPI/(.*?)/(.*?)/(.*?)/(\d+)/(.*)', description)
        if match_upi:
            parsed_data['utr_number'] = match_upi.group(4) # UTR number is in the 4th group
            parsed_data['details'] = match_upi.group(2).strip() # Comment (details) is in the 2nd group
            parsed_data['payment_method'] = 'UPI' # Set payment method to UPI
        elif 'NEFT-' in description:
            parsed_data['payment_method'] = 'NEFT' # Set payment method to NEFT
            neft_match = re.search(r'NEFT-([^-]+)-(.*)', description)
            if neft_match:
                parsed_data['utr_number'] = neft_match.group(1) # NEFT UTR/Reference
                parsed_data['details'] = neft_match.group(2).strip()
        elif 'IMPS/' in description:
            parsed_data['payment_method'] = 'IMPS' # Set payment method to IMPS
            imps_match = re.search(r'IMPS/(\d+)/(\d+)/(.*?)/', description)
            if imps_match:
                parsed_data['utr_number'] = imps_match.group(1) # IMPS reference
                # details could be the third group or combination
                parsed_data['details'] = f"IMPS A/C: {imps_match.group(2)}, Details: {imps_match.group(3).strip()}"
        # Handle NACH transactions (look for patterns like 'NACH')
        elif 'NACH' in description or 'ACH' in description:
            parsed_data['payment_method'] = 'NACH'
            parsed_data['details'] = description # Keep full description for NACH details initially
        # Handle ATM withdrawals
        elif 'ATM WDL' in description:
            parsed_data['payment_method'] = 'ATM Withdrawal'
            parsed_data['details'] = description
        # Handle POS transactions
        elif 'POS' in description:
             parsed_data['payment_method'] = 'POS'
             parsed_data['details'] = description
        # Add more patterns as needed for other transaction types
        else:
             parsed_data['details'] = description
             parsed_data['utr_number'] = None
             parsed_data['payment_method'] = 'Other' # Default to 'Other'

    return parsed_data


