def convert_icici_to_txn_dto(data) -> TransactionDTO:
    """
    Converts a dictionary from an ICICI bank transaction row into a TransactionDTO.
    """
    # Extract data from the dictionary based on ICICI column names
    txn_date = data.get('Transaction Date')
