    reference_number = data.get('reference_number')
    payment_method = data.get('payment_method') # Get payment_method from DataFrame


    # Convert date to date object if it's not already
    transaction_date = None
    if isinstance(txn_date, str):
        try:
            # Assuming 'date' is already in 'YYYY-MM-DD' format from previous cleaning
            transaction_date = datetime.strptime(txn_date, '%Y-%m-%d').date()
        except ValueError:
             # If date format is different, try other common formats or handle appropriately
             print(f"Could not parse date from string: {txn_date}")
             return None
    elif isinstance(txn_date, (pd.Timestamp, datetime, date)): # Handle if already date/datetime object
         transaction_date = txn_date if isinstance(txn_date, date) else txn_date.date()
    else:
        # If txn_date is None or unexpected type, skip this row
        print(f"Skipping row due to invalid date type: {type(txn_date)}")
        return None


    # Ensure amount is a float
    try:
        amount = float(amount) if pd.notna(amount) else 0.0
    except ValueError:
        print(f"Could not convert amount to float: {amount}")
        return None


    # Create TransactionDTO object
    if txn_type is not None and transaction_date is not None and amount is not None: # Only create DTO if essential data is determined
        dto = TransactionDTO(
            id=uuid.uuid4(), # Generate a unique ID for the DTO
            date=transaction_date,
            amount=amount,
            bank_description=description,
            details=details,
            txn_type=txn_type,
            bank_name="PhonePe", # Set bank name to PhonePe
            payment_method=payment_method, # Assign payment_method from DataFrame
            transaction_id=transaction_id,
            utr_number=utr_number,
            audit_status=None, # PhonePe data doesn't have this, default None
            duplicate_transaction_id=None, # PhonePe data doesn't have this, default None
            reference_number=reference_number
        )
        return dto

    # print(f"Skipping invalid transaction row: {data}")
    return None


