def get_transactions_list(data,f) -> List[TransactionDTO]:
  transaction_dto_list = []

  # Iterate over the rows of the DataFrame and convert each row to a TransactionDTO
  for index, row in data.iterrows():
      transaction_dict = row.to_dict()
      # print(transaction_dict)
      dto = f(transaction_dict)
      if dto:  # Only append if the conversion was successful and returned a DTO
          transaction_dto_list.append(dto)

  print(f"Created {len(transaction_dto_list)} TransactionDTO objects.")
  return transaction_dto_list

def save_data_to_csv(transaction_dto_list:List[TransactionDTO],file_name='sbi_transactions.csv'):

  # Convert list of TransactionDTO objects to a list of dictionaries
  data_for_df = [dto.__dict__ for dto in transaction_dto_list]

  # Convert the list of dictionaries to a pandas DataFrame
  df_output = pd.DataFrame(data_for_df)

  # Define the output CSV file path
  output_csv_filepath = os.path.join(bank_txn_path, file_name)

  # Save the DataFrame to a CSV file
  df_output.to_csv(output_csv_filepath, index=False)

  print(f"Successfully saved transaction data to CSV file: {output_csv_filepath}")



def extract_text_from_pdf(pdf_path):
    """
    Extracts text from a PDF file using PyMuPDF.
    """
    doc = fitz.open(phonepe_pdf_path)
    text = ""
    for page_num in range(doc.page_count):
        page = doc.load_page(page_num)
        text += page.get_text()
    return text

def parse_phonepe_transactions(text):
    """
    Parses the text of a PhonePe statement to extract transaction data.

    Args:
        text: The string content of the PhonePe statement.

    Returns:
        A list of dictionaries, where each dictionary represents a transaction.
    """
    transactions = []
    # Regex to find each transaction block, which starts with a date and time
    transaction_blocks = re.split(r'\n(?=\w{3}\s\d{2},\s\d{4}\n\d{2}:\d{2}\s[AP]M)', text)

    for block in transaction_blocks:
        if not block.strip() or "Transaction Statement for" in block:
            continue

        try:
            # Extracting date and time
            date_match = re.search(r'(\w{3}\s\d{2},\s\d{4})', block)
            time_match = re.search(r'(\d{2}:\d{2}\s[AP]M)', block)
            date = date_match.group(1) if date_match else None
            time = time_match.group(1) if time_match else None

            # Extracting transaction type and amount
            type_amount_match = re.search(r'(DEBIT|CREDIT)\s₹([\d,]+\.?\d*)', block)
            txn_type = type_amount_match.group(1) if type_amount_match else None
            amount_str = type_amount_match.group(2) if type_amount_match else '0'
            amount = float(amount_str.replace(',', ''))

            # Extracting Transaction ID
            txn_id_match = re.search(r'Transaction ID\s(.+?)\n', block)
            transaction_id = txn_id_match.group(1).strip() if txn_id_match else None

            # Extracting UTR No.
            utr_match = re.search(r'UTR No\.\s(.+?)\n', block)
            utr_number = utr_match.group(1).strip() if utr_match else None

            # Extracting Paid by/Credited to
            paid_by_match = re.search(r'Paid by\n(.+?)\n', block)
            credited_to_match = re.search(r'Credited to\n(.+?)\n', block)
            account = paid_by_match.group(1).strip() if paid_by_match else (credited_to_match.group(1).strip() if credited_to_match else None)

            # Extracting Transaction Details
            details_match = re.search(r'\d{2}:\d{2}\s[AP]M\n(.*?)\nTransaction ID', block, re.DOTALL)
            details = details_match.group(1).strip().replace('\n', ' ') if details_match else None

            if date and time and txn_type and amount is not None:
                transactions.append({
                    "Date": date,
                    "Time": time,
                    "Transaction Details": details,
                    "Type": txn_type,
                    "Amount": amount,
                    "Transaction ID": transaction_id,
                    "UTR No.": utr_number,
                    "Account": account
                })
        except Exception as e:
            print(f"Error parsing block: {block}\n{e}")
    return pd.DataFrame(transactions)


