  if 'payment_method' not in phonepe_df.columns:
      phonepe_df['payment_method'] = 'UPI'


  # Reorder columns to match TransactionDTO schema before conversion
  phonepe_df = phonepe_df[['id', 'date', 'amount', 'bank_description', 'details', 'txn_type',
                          'bank_name', 'payment_method', 'transaction_id', 'utr_number', 'audit_status',
                          'duplicate_transaction_id', 'reference_number']]
  return phonepe_df

