combined_bank_txn = pd.concat([sbi, icici], ignore_index=True)
combined_bank_txn['system_comment'] = None

def audit_bank_transactions(bank_txn, phonepe):
  combined_bank_transactions_df = bank_txn.copy()
  phonepe_df_copy = phonepe.copy() # Create a copy to track matched status

  combined_bank_transactions_df['date'] = pd.to_datetime(combined_bank_transactions_df['date'])
  phonepe_df_copy['date'] = pd.to_datetime(phonepe_df_copy['date'])

  amount_tolerance = 0.01
  date_tolerance = pd.Timedelta(days=1)

  matched_phonepe_indices = set()

  for bank_index, bank_txn_row in combined_bank_transactions_df.iterrows():
      match_found = False
      for phonepe_index, phonepe_txn_row in phonepe_df_copy.iterrows():
          utr_match = False
          if pd.notna(phonepe_txn_row['utr_number']) and pd.notna(bank_txn_row['utr_number']):
              phonepe_utr_str = str(phonepe_txn_row['utr_number']).split('.')[0] if isinstance(phonepe_txn_row['utr_number'], float) else str(phonepe_txn_row['utr_number'])
              bank_utr_str = str(bank_txn_row['utr_number']).split('.')[0] if isinstance(bank_txn_row['utr_number'], float) else str(bank_txn_row['utr_number'])
              if phonepe_utr_str == bank_utr_str:
                  utr_match = True

          date_match = False
          if pd.notna(phonepe_txn_row['date']) and pd.notna(bank_txn_row['date']):
              date_match = abs(phonepe_txn_row['date'] - bank_txn_row['date']) <= date_tolerance

          amount_match = False
          if pd.notna(phonepe_txn_row['amount']) and pd.notna(bank_txn_row['amount']):
              if (abs(phonepe_txn_row['amount'] - bank_txn_row['amount']) <= amount_tolerance):
                  amount_match = True

          if utr_match or (date_match and amount_match):
              combined_bank_transactions_df.loc[bank_index, 'audit_status'] = 'MATCHED'
              combined_bank_transactions_df.loc[bank_index, 'system_comment'] = 'Found in PhonePe'
              matched_phonepe_indices.add(phonepe_index)
              match_found = True
              break
      if not match_found:
          if pd.isna(combined_bank_transactions_df.loc[bank_index, 'audit_status']): # Only if not already matched
              combined_bank_transactions_df.loc[bank_index, 'audit_status'] = 'UNMATCHED'
              combined_bank_transactions_df.loc[bank_index, 'system_comment'] = 'No match found in PhonePe data'

  unmatched_phonepe_transactions_df = phonepe[~phonepe.index.isin(matched_phonepe_indices)].copy()
  unmatched_phonepe_transactions_df['audit_status'] = 'UNMATCHED'
  unmatched_phonepe_transactions_df['system_comment'] = 'No match found in Bank data'

  return combined_bank_transactions_df, unmatched_phonepe_transactions_df

combined_bank_transactions_df, unmatched_phonepe_transactions_df = audit_bank_transactions(combined_bank_txn, phonepe)

